{
  "root": "main_stack",
  "state": {
    "budget_data": [
      {
        "day": "April 10: Arashiyama Focus",
        "accommodation": "$250",
        "food": "$100",
        "fees": "$120",
        "total": "$470"
      },
      {
        "day": "April 11: Gion & Kaiseki Excellence",
        "accommodation": "$250",
        "food": "$450",
        "fees": "$40",
        "total": "$740"
      },
      {
        "day": "April 12: Zen Gardens & Shopping",
        "accommodation": "$250",
        "food": "$120",
        "fees": "$60",
        "total": "$430"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h1",
        "intro_text",
        "itinerary_h2",
        "day1_card",
        "day2_card",
        "day3_card",
        "budget_h2",
        "budget_context_text",
        "budget_table",
        "transit_h2",
        "transit_intro_text",
        "transit_list",
        "quick_actions_h2",
        "suica_button"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Kyoto Spring Cultural Escape",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This 3-day itinerary focuses on the serene Zen temples and refined culinary traditions of Kyoto during the peak cherry blossom season. With a total budget of $1,500 USD (approx. ¥225,000 JPY), you will experience high-end Kaiseki dining and tranquil tea ceremonies at a moderate, contemplative pace."
      },
      "children": []
    },
    "itinerary_h2": {
      "type": "Text",
      "props": {
        "text": "Three-Day Zen and Tradition Itinerary",
        "variant": "h2"
      },
      "children": []
    },
    "day1_card": {
      "type": "Card",
      "props": {},
      "children": [
        "day1_image",
        "day1_header_stack",
        "day1_list",
        "day1_button"
      ]
    },
    "day1_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Tenryu-ji_Sogenchi_Garden_2012.JPG/1200px-Tenryu-ji_Sogenchi_Garden_2012.JPG"
      },
      "children": []
    },
    "day1_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "day1_icon",
        "day1_title_text"
      ]
    },
    "day1_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/tree.svg"
      },
      "children": []
    },
    "day1_title_text": {
      "type": "Text",
      "props": {
        "text": "Day 1: Arashiyama Zen and Bamboo Groves",
        "variant": "h3"
      },
      "children": []
    },
    "day1_list": {
      "type": "List",
      "props": {},
      "children": [
        "day1_item1",
        "day1_item2",
        "day1_item3"
      ]
    },
    "day1_item1": {
      "type": "Text",
      "props": {
        "text": "Tenryu-ji Temple: Explore this head Zen temple and its 14th-century Sogenchi Garden, designed to frame the surrounding mountains."
      },
      "children": []
    },
    "day1_item2": {
      "type": "Text",
      "props": {
        "text": "Arashiyama Bamboo Grove: Walk the ethereal path through towering bamboo stalks located immediately behind the temple grounds."
      },
      "children": []
    },
    "day1_item3": {
      "type": "Text",
      "props": {
        "text": "Traditional Tea Ceremony: Participate in a private, meditative tea preparation at a local machiya overlooking the Hozugawa River."
      },
      "children": []
    },
    "day1_button": {
      "type": "Button",
      "props": {
        "label": "View Tenryu-ji Info"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.tenryuji.com/en/"
          }
        }
      },
      "children": []
    },
    "day2_card": {
      "type": "Card",
      "props": {},
      "children": [
        "day2_image",
        "day2_header_stack",
        "day2_list",
        "day2_button"
      ]
    },
    "day2_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a2/Kiyomizu-dera_in_Kyoto-r.jpg/1200px-Kiyomizu-dera_in_Kyoto-r.jpg"
      },
      "children": []
    },
    "day2_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "day2_icon",
        "day2_title_text"
      ]
    },
    "day2_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/building.svg"
      },
      "children": []
    },
    "day2_title_text": {
      "type": "Text",
      "props": {
        "text": "Day 2: Higashiyama Heritage and Kaiseki Dining",
        "variant": "h3"
      },
      "children": []
    },
    "day2_list": {
      "type": "List",
      "props": {},
      "children": [
        "day2_item1",
        "day2_item2",
        "day2_item3"
      ]
    },
    "day2_item1": {
      "type": "Text",
      "props": {
        "text": "Kiyomizu-dera Temple: Visit this iconic wooden temple at sunrise to appreciate the panoramic views of Kyoto and the cherry blossoms."
      },
      "children": []
    },
    "day2_item2": {
      "type": "Text",
      "props": {
        "text": "Kodai-ji Temple: Experience the stunning Zen gardens and \"weeping\" cherry trees at this temple established in 1606."
      },
      "children": []
    },
    "day2_item3": {
      "type": "Text",
      "props": {
        "text": "Authentic Kaiseki Dinner: Enjoy a multi-course seasonal feast at a Michelin-starred establishment in the historic Gion district."
      },
      "children": []
    },
    "day2_button": {
      "type": "Button",
      "props": {
        "label": "Reserve Kaiseki"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.tableall.com/restaurant/135"
          }
        }
      },
      "children": []
    },
    "day3_card": {
      "type": "Card",
      "props": {},
      "children": [
        "day3_image",
        "day3_header_stack",
        "day3_list",
        "day3_button"
      ]
    },
    "day3_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/12/Ryoanji_Temple_Kyoto_Japan.jpg/1200px-Ryoanji_Temple_Kyoto_Japan.jpg"
      },
      "children": []
    },
    "day3_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "day3_icon",
        "day3_title_text"
      ]
    },
    "day3_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/signpost-split.svg"
      },
      "children": []
    },
    "day3_title_text": {
      "type": "Text",
      "props": {
        "text": "Day 3: The Art of Zen Rock Gardens",
        "variant": "h3"
      },
      "children": []
    },
    "day3_list": {
      "type": "List",
      "props": {},
      "children": [
        "day3_item1",
        "day3_item2",
        "day3_item3"
      ]
    },
    "day3_item1": {
      "type": "Text",
      "props": {
        "text": "Ryoan-ji Temple: Contemplate the world's most famous Zen rock garden, consisting of 15 stones arranged in a sea of white gravel."
      },
      "children": []
    },
    "day3_item2": {
      "type": "Text",
      "props": {
        "text": "Kinkaku-ji (Golden Pavilion): View the gold-leaf-covered Zen temple reflecting in the \"Mirror Pond\" amidst spring blooms."
      },
      "children": []
    },
    "day3_item3": {
      "type": "Text",
      "props": {
        "text": "Sannenzaka & Ninenzaka Walk: Conclude with a slow stroll through preserved streets for traditional crafts and incense shopping."
      },
      "children": []
    },
    "day3_button": {
      "type": "Button",
      "props": {
        "label": "Ryoan-ji Guide"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "http://www.ryoanji.jp/smhp/eng/"
          }
        }
      },
      "children": []
    },
    "budget_h2": {
      "type": "Text",
      "props": {
        "text": "Daily Budget and Expense Allocation",
        "variant": "h2"
      },
      "children": []
    },
    "budget_context_text": {
      "type": "Text",
      "props": {
        "text": "The budget accounts for peak cherry blossom pricing in April 2025. All figures are for two people."
      },
      "children": []
    },
    "budget_table": {
      "type": "Table",
      "props": {
        "columns": [
          { "key": "day", "label": "Day" },
          { "key": "accommodation", "label": "Accommodation" },
          { "key": "food", "label": "Food" },
          { "key": "fees", "label": "Fees" },
          { "key": "total", "label": "Total" }
        ],
        "statePath": "/budget_data",
        "domain": "comparison",
        "preferredPresentation": "cards",
        "primaryColumn": "day",
        "numericColumns": ["accommodation", "food", "fees", "total"]
      },
      "children": []
    },
    "transit_h2": {
      "type": "Text",
      "props": {
        "text": "Local Transit Recommendations",
        "variant": "h2"
      },
      "children": []
    },
    "transit_intro_text": {
      "type": "Text",
      "props": {
        "text": "Kyoto's public transport system is efficient and easy to navigate. Consider these options:"
      },
      "children": []
    },
    "transit_list": {
      "type": "List",
      "props": {},
      "children": [
        "transit_item1",
        "transit_item2",
        "transit_item3"
      ]
    },
    "transit_item1": {
      "type": "Text",
      "props": {
        "text": "Kyoto City Bus: Extensive network covering most tourist attractions. Day passes are available."
      },
      "children": []
    },
    "transit_item2": {
      "type": "Text",
      "props": {
        "text": "Subway: Two main lines (Karasuma and Tozai) are useful for north-south and east-west travel."
      },
      "children": []
    },
    "transit_item3": {
      "type": "Text",
      "props": {
        "text": "JR Sagano Line: Convenient for reaching Arashiyama from Kyoto Station."
      },
      "children": []
    },
    "quick_actions_h2": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "suica_button": {
      "type": "Button",
      "props": {
        "label": "Purchase ICOCA/SUICA Card"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.japan-guide.com/e/e2359_003.html"
          }
        }
      },
      "children": []
    }
  }
}
